import express, { Express } from "express";
import { OrderService } from "../application/order-service";
import { OrderController } from "./order-controller";
import { InMemoryOrderRepository, InMemoryProductRepository } from "./in-memory-repositories";

/** Creates the HTTP API with its process-local in-memory data store. */
export function createApp(): Express {
  const app = express();
  const service = new OrderService(new InMemoryOrderRepository(), new InMemoryProductRepository());
  app.use(express.json());
  app.use(new OrderController(service).router());
  return app;
}

if (require.main === module) {
  const port = Number(process.env.PORT ?? 3000);
  createApp().listen(port, () => console.log(`Order fulfilment API listening on ${port}`));
}

